/**
 * 联合指挥交接单状态：PENDING 预览冻结待接受，ACCEPTED 已接受并整体切换指挥权。
 */
public enum HandoverStatus {

    /** 待接受：闭包与冻结摘要已生成，指挥权尚未切换。 */
