/**
 * 迭代求未解决依赖闭包：每轮沿当前锁定集合内事件的 OPEN 任务未完成阻塞边扩展，
 * 新到达事件按 id 升序锁定后重算，直到集合不再增长。
 */
private List<Incident> expandAndLockClosure(List<Long> seedIds) {
    List<Long> lockedIds = List.copyOf(seedIds);
    while (true) {
        List<Long> frontier = new ArrayList<>(lockedIds);
        // 只沿未完成阻塞关系扩展：阻塞事件已 CONTAINED/RESOLVED/CLOSED 的边跳过
        Map<Long, Incident> known = incidents.listByIdsOrdered(frontier).stream()
                .collect(LinkedHashMap::new, (m, i) -> m.put(i.id(), i), Map::putAll);
        Set<Long> reachable = new LinkedHashSet<>(lockedIds);
        for (var edge : tasks.listOpenBlockerEdgesByFromIncidents(new ArrayList<>(reachable))) {
            long target = edge.toIncidentId();
            Incident targetIncident = known.get(target);
            if (targetIncident == null) {
                targetIncident = incidents.listByIdsOrdered(List.of(target)).stream()
                        .findFirst().orElse(null);
                if (targetIncident == null) {
                    continue;
                }
                known.put(target, targetIncident);
            }
            if (!FINISHED_BLOCK_STATUSES.contains(targetIncident.status())) {
                reachable.add(target);
            }
        }
        List<Long> nextLocked = reachable.stream().sorted().toList();
        if (nextLocked.size() == lockedIds.size()) {
            return incidents.lockByIdsOrdered(nextLocked);
        }
        // 锁定新到达事件后重算（并发新建边必须持有其来源事件行锁，锁定后无法再提交）
        incidents.lockByIdsOrdered(nextLocked);
        lockedIds = nextLocked;
    }
}

