                HttpStatus.BAD_REQUEST);
        // 接收人就是发起人
        assertApiStatus(() -> initiate("H-S4", "alice", "alice", List.of("A", "B")),
                HttpStatus.BAD_REQUEST);
        // 混入终态（RESOLVED）事件：其无 OPEN 任务时可直达 RESOLVED
